```sql
SELECT a.total_general_credits-b.total_general_credits AS total_credit_reduction,ra.min_credits-rb.min_credits AS distribution_credit_reduction FROM general_education_requirements a JOIN general_education_requirements b ON 1=1 JOIN general_education_requirement_categories ra ON ra.general_requirement_id=a.general_requirement_id JOIN general_education_requirement_categories rb ON rb.general_requirement_id=b.general_requirement_id WHERE 2023 BETWEEN a.cohort_start AND a.cohort_end AND 2024 BETWEEN b.cohort_start AND b.cohort_end AND ra.requirement_code='DISTRIBUTION' AND rb.requirement_code='DISTRIBUTION';
